import { HEIGHTMAP_BAKE_VERSION } from "./heightmap-presets";

/**
 * Loads the heightmaps baked by `npm run bake`.
 *
 * Every map here can also be generated in the browser, and that is the
 * fallback on any failure - a missing manifest, a stale bake, a fetch that
 * never lands. That is deliberate: the baked files are a speed-up, not a
 * dependency, and a site that shows no mountain because a static file 404s
 * would be a worse trade than one that takes half a second longer on the
 * first paint. Every fallback says so in the console in dev.
 */

interface ManifestEntry {
  file: string;
  resolution: number;
  kind: string;
}

interface Manifest {
  version: number;
  encoding: string;
  maps: Record<string, ManifestEntry>;
}

const BASE = `${import.meta.env.BASE_URL}heightmaps/`;

/**
 * Quantisation depth of the baked files. Must match BITS in
 * scripts/bake-heightmaps.mjs, which is also where the wire format and the
 * reasoning behind it are written down.
 */
const HEIGHTMAP_BITS = 12;
const MAX_LEVEL = (1 << HEIGHTMAP_BITS) - 1;
const ENCODING = `delta${HEIGHTMAP_BITS}-split`;

/**
 * Undoes the bake's byte-split, zigzag and row-delta, in that order, and
 * scales back to 0..1 - exactly what the generator would have returned.
 */
function decode(bytes: Uint8Array, size: number): Float32Array {
  const count = size * size;
  const heights = new Float32Array(count);
  const low = count;
  for (let y = 0; y < size; y++) {
    let previous = 0;
    for (let x = 0; x < size; x++) {
      const i = y * size + x;
      const zig = (bytes[i] << 8) | bytes[low + i];
      // Inverse zigzag. The shift has to be unsigned or the sign bit walks
      // back in on every negative delta.
      previous += (zig >>> 1) ^ -(zig & 1);
      heights[i] = previous / MAX_LEVEL;
    }
  }
  return heights;
}

function warn(message: string): void {
  if (import.meta.env.DEV) console.warn(`[heightmaps] ${message} - generating at runtime instead.`);
}

/**
 * The maps for this session, by key ("massif-1025", "horizon-513"). A key
 * that is absent simply means "generate it"; callers must not treat a miss
 * as an error.
 */
export type HeightmapBundle = Map<string, Float32Array>;

/**
 * Fetches the named maps in parallel and decodes them back to the 0..1
 * floats the generators would have produced.
 *
 * Never rejects. Only the keys that actually arrived, intact and at the
 * expected size, are in the returned map.
 */
export async function loadBakedHeightmaps(keys: readonly string[]): Promise<HeightmapBundle> {
  const bundle: HeightmapBundle = new Map();
  if (keys.length === 0) return bundle;

  let manifest: Manifest;
  try {
    const response = await fetch(`${BASE}manifest.json`);
    if (!response.ok) throw new Error(`manifest ${response.status}`);
    manifest = (await response.json()) as Manifest;
  } catch (error) {
    warn(`could not read the manifest (${String(error)})`);
    return bundle;
  }

  if (manifest.encoding !== ENCODING) {
    warn(`bake is encoded as "${manifest.encoding}", this build reads "${ENCODING}"`);
    return bundle;
  }

  if (manifest.version !== HEIGHTMAP_BAKE_VERSION) {
    // The terrain's parameters have moved since the bake. The files on disk
    // describe a different mountain, and using them would put the trail,
    // the camera clearances and the snowline on terrain none of them were
    // measured against.
    warn(
      `bake is version ${manifest.version}, this build wants ${HEIGHTMAP_BAKE_VERSION} (run: npm run bake)`,
    );
    return bundle;
  }

  await Promise.all(
    keys.map(async (key) => {
      const entry = manifest.maps?.[key];
      if (!entry) {
        warn(`no baked "${key}"`);
        return;
      }
      try {
        const response = await fetch(`${BASE}${entry.file}`);
        if (!response.ok) throw new Error(`${entry.file} ${response.status}`);
        const buffer = await response.arrayBuffer();
        // Two planes of one byte per sample. Guards a truncated or
        // mis-keyed file, which would otherwise decode into a mountain with
        // a torn edge rather than fail.
        const expected = entry.resolution * entry.resolution * 2;
        if (buffer.byteLength !== expected) {
          throw new Error(`${entry.file} is ${buffer.byteLength} bytes, expected ${expected}`);
        }
        bundle.set(key, decode(new Uint8Array(buffer), entry.resolution));
      } catch (error) {
        warn(String(error));
      }
    }),
  );

  return bundle;
}
